export const saveCondoName = (name: string) => {
  localStorage.setItem(STORAGE_KEYS.CONDO_NAME, name);
  if (name) syncToCloud(STORAGE_KEYS.CONDO_NAME, name);
  if (db && name && name !== 'Modo Administrativo') {
